return ['domain'=>'gtfs-timetables','plural-forms'=>'nplurals=3; plural=(n==1 ? 0 : n%10>=2 && n%10<=4 && (n%100<12 || n%100>14) ? 1 : 2);','language'=>'pl_PL','project-id-version'=>'GTFS Timetables 0.1.0','pot-creation-date'=>'2026-10-23T19:11:43+00:00','po-revision-date'=>'2026-10-24T07:02:08+00:00','x-generator'=>'WP-CLI 2.12.0','messages'=>['GTFS Timetables'=>'Rozkłady jazdy GTFS','Shows public transport schedules from a GTFS feed.'=>'Wyświetla rozkłady jazdy komunikacji publicznej z feedu GTFS.','PUBLICTRANSITDATA.NET'=>'PUBLICTRANSITDATA.NET','The file is larger than this site accepts (%s). Import it from a URL or with WP-CLI instead.'=>'Plik jest większy, niż pozwala ta witryna (%s). Zaimportuj go z adresu URL lub przez WP-CLI.','Choose a GTFS .zip file first.'=>'Najpierw wybierz plik GTFS w formacie .zip.','The upload failed (PHP error %d).'=>'Przesyłanie nie powiodło się (błąd PHP %d).','The file is not a .zip archive. A GTFS feed is published as a .zip of .txt files.'=>'Plik nie jest archiwum .zip. Feed GTFS jest publikowany jako archiwum .zip z plikami .txt.','You are not allowed to import feeds.'=>'Nie masz uprawnień do importowania feedów.','Feed URL'=>'Adres URL feedu','Link to the GTFS .zip published by the transport operator.'=>'Link do archiwum GTFS .zip publikowanego przez przewoźnika.','Update automatically'=>'Aktualizuj automatycznie','Runs at night through WP-Cron. On sites with little traffic, set up a real cron job for wp-cron.php or use WP-CLI: wp gtfs-timetables import'=>'Uruchamia się w nocy przez WP-Cron. Na witrynach z małym ruchem skonfiguruj prawdziwe zadanie cron dla wp-cron.php lub użyj WP-CLI: wp gtfs-timetables import','Data source credit'=>'Źródło danych','Shown under timetables. Many open data licences require crediting the publisher, e.g. "Data: City transport authority, CC BY 4.0". Leave empty to show nothing.'=>'Wyświetlane pod rozkładami. Wiele licencji otwartych danych wymaga podania źródła, np. „Dane: Zarząd Transportu Miejskiego, CC BY 4.0”. Zostaw puste, aby nic nie wyświetlać.','Import'=>'Import','Current data imported %1$s. Feed time zone: %2$s.'=>'Bieżące dane zaimportowano %1$s. Strefa czasowa feedu: %2$s.','This feed describes some trips with frequencies.txt ("every 10 minutes"). Those trips are not shown yet.'=>'Część kursów w tym feedzie opisano w pliku frequencies.txt („co 10 minut”). Takie kursy nie są jeszcze wyświetlane.','Uploading the file…'=>'Przesyłanie pliku…','Import from feed URL'=>'Importuj z adresu URL','Or upload a GTFS .zip file:'=>'Lub prześlij plik GTFS .zip:','Upload and import'=>'Prześlij i zaimportuj','Maximum file size: %s. For larger feeds use the feed URL or WP-CLI: wp gtfs-timetables import --file=feed.zip'=>'Maksymalny rozmiar pliku: %s. W przypadku większych feedów użyj adresu URL lub WP-CLI: wp gtfs-timetables import --file=feed.zip','Automatic updates import from the feed URL and will replace data from an uploaded file.'=>'Automatyczne aktualizacje importują feed z adresu URL i zastąpią dane z przesłanego pliku.','Re-import even if the feed has not changed'=>'Importuj ponownie, nawet jeśli feed się nie zmienił','Find a stop'=>'Znajdź przystanek','Stop name, code or id'=>'Nazwa, kod lub ID przystanku','Search'=>'Szukaj','No stops found.'=>'Nie znaleziono przystanków.','Stop'=>'Przystanek','Code'=>'Kod','Shortcodes'=>'Shortcode’y','station, includes all its platforms'=>'stacja, obejmuje wszystkie jej perony','%s has no header row.'=>'Plik %s nie ma wiersza nagłówka.','Could not download the feed: %s'=>'Nie udało się pobrać feedu: %s','filesystem is not writable'=>'brak uprawnień do zapisu w systemie plików','Could not unpack the feed: %s'=>'Nie udało się rozpakować feedu: %s','The feed is missing required files: %s'=>'W feedzie brakuje wymaganych plików: %s','Line %s'=>'Linia %s','GTFS Timetables: no feed has been imported yet.'=>'Rozkłady jazdy GTFS: nie zaimportowano jeszcze żadnego feedu.','GTFS Timetables: the feed has no lines of the chosen transport modes.'=>'Rozkłady jazdy GTFS: w feedzie nie ma linii wybranych środków transportu.','This line is not in the current timetable. Choose a line:'=>'Tej linii nie ma w obowiązującym rozkładzie. Wybierz linię:','GTFS Timetables: there is no stop with id "%s" in the feed.'=>'Rozkłady jazdy GTFS: w feedzie nie ma przystanku o ID „%s”.','Could not write to %1$s: %2$s'=>'Nie udało się zapisać do %1$s: %2$s','Another import is running. Try again when it has finished.'=>'Trwa inny import. Spróbuj ponownie, gdy się zakończy.','Unpacking the feed…'=>'Rozpakowywanie feedu…','Downloading the feed…'=>'Pobieranie feedu…','Importing %1$s: %2$d%% (%3$s rows so far)'=>'Import %1$s: %2$d%% (wczytane wiersze: %3$s)','Finishing…'=>'Kończenie…','No import has run yet.'=>'Import nie był jeszcze uruchamiany.','The feed has not changed since the last import.'=>'Feed nie zmienił się od ostatniego importu.','Set the feed URL first.'=>'Najpierw podaj adres URL feedu.','The feed has no usable stop times.'=>'Feed nie zawiera użytecznych godzin odjazdów.','Import finished: %1$s stops, %2$s trips, %3$s stop times.'=>'Import zakończony. Przystanki: %1$s, kursy: %2$s, godziny odjazdów: %3$s.','Night lines'=>'Linie nocne','Metro line'=>'Linia metra','Tram line'=>'Linia tramwajowa','Trolleybus line'=>'Linia trolejbusowa','Bus line'=>'Linia autobusowa','Train line'=>'Linia kolejowa','Ferry line'=>'Linia promowa','Cable car line'=>'Kolej linowa','Transit line'=>'Linia','Metro'=>'Metro','Trams'=>'Tramwaje','Trolleybuses'=>'Trolejbusy','Buses'=>'Autobusy','Trains'=>'Pociągi','Ferries'=>'Promy','Cable cars and funiculars'=>'Koleje linowe i linowo-terenowe','Other lines'=>'Inne linie','now'=>'teraz','in %d min'=>'za %d min' . "\0" . 'za %d min' . "\0" . 'za %d min','Manual only'=>'Tylko ręcznie','Daily'=>'Codziennie','Weekly'=>'Co tydzień','No departures scheduled.'=>'Brak zaplanowanych odjazdów.','Line'=>'Linia','Direction'=>'Kierunek','Departs'=>'Odjazd','This line has no trips in the current timetable.'=>'W obowiązującym rozkładzie ta linia nie ma kursów.','Directions'=>'Kierunki','Towards %s'=>'Kierunek: %s','Stops'=>'Przystanki','This is the last stop of the line in this direction, so it has no departures.'=>'To przystanek końcowy linii w tym kierunku, więc nie ma z niego odjazdów.','Choose a day'=>'Wybierz dzień','Previous day'=>'Poprzedni dzień','Next day'=>'Następny dzień','No departures on this day.'=>'Brak odjazdów w tym dniu.','block titleLine timetable'=>'Rozkład linii','block descriptionThe line a visitor chose in a Lines block. Put it on one page: every Lines block on the site links there.'=>'Linia wybrana przez odwiedzającego w bloku „Linie”. Umieść go na jednej stronie: wszystkie bloki „Linie” w witrynie prowadzą właśnie tam.','block keywordroute'=>'trasa','block keywordtimetable'=>'rozkład jazdy','block keywordGTFS'=>'GTFS','block titleLines'=>'Linie','block descriptionAll lines of the network, grouped by transport mode.'=>'Wszystkie linie sieci, pogrupowane według środka transportu.','block keywordroutes'=>'trasy','block keywordnetwork'=>'sieć']];